import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import os
import json
PROJECT_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
output_dir = os.path.join(PROJECT_ROOT, "results")
os.makedirs(output_dir, exist_ok=True)

# ---------------------------------------------------------
# REAL-OPTIONS ASSET PRICING FORMULATION FOR AI AGENTS
# ---------------------------------------------------------
# Dixit-Pindyck / Black-Scholes framework adapted to micro-capital allocation:
# - Underlying Asset (S): Expected present value of information / alpha generated by agent
# - Strike Price (K): Transaction cost = gas fee + micropayment (x402)
# - Volatility (sigma): Uncertainty in information payoff or tokenized asset volatility
# - Risk-free rate (r): Opportunity cost of capital (annualized or per-period)
# - Time to expiration (T): Latency window before information decays (e.g., 5 seconds to 1 hour)

def black_scholes_call(S, K, T, r, sigma):
    from scipy.stats import norm
    if T <= 0 or sigma <= 0:
        return np.maximum(S - K, 0.0)
    d1 = (np.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
    d2 = d1 - sigma * np.sqrt(T)
    call_val = S * norm.cdf(d1) - K * np.exp(-r * T) * norm.cdf(d2)
    return call_val

# Scipy check
try:
    from scipy.stats import norm
except ImportError:
    import urllib.request
    # Fallback numerical approximation if scipy not installed
    def erf(x):
        # erf approximation
        sign = 1 if x >= 0 else -1
        x = abs(x)
        a1, a2, a3, a4, a5 = 0.254829592, -0.284496736, 1.421413741, -1.453152027, 1.061405429
        p = 0.3275911
        t = 1.0 / (1.0 + p * x)
        y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * np.exp(-x * x)
        return sign * y

    class norm:
        @staticmethod
        def cdf(x):
            return 0.5 * (1.0 + erf(x / np.sqrt(2.0)))

# 1. Parameter Definitions
r = 0.05               # 5% annual risk-free rate
T_micro = 1.0 / (365 * 24 * 60) # 1-minute expiration window for micro-arbitrage/query
sigma = 0.80           # High volatility of crypto/tokenized alpha (80% annualized)

# Traditional Fiat Payment Rail (Visa/Mastercard)
K_fiat = 0.30          # $0.30 fixed interchange minimum fee

# Blockchain Micropayment Rail (x402 on Base L2)
# Average Base L2 transaction fee = $0.0005, typical x402 query price = $0.001 - $0.005
K_blockchain_low = 0.0015   # $0.0015 (sub-cent rail)
K_blockchain_high = 0.0100  # $0.0100 (1 cent compute call)

# Spectrum of micro-information payoffs S (from $0.0001 up to $0.50)
S_values = np.linspace(0.0001, 0.50, 500)

option_vals_fiat = [black_scholes_call(s, K_fiat, T_micro, r, sigma) for s in S_values]
option_vals_bc_low = [black_scholes_call(s, K_blockchain_low, T_micro, r, sigma) for s in S_values]
option_vals_bc_high = [black_scholes_call(s, K_blockchain_high, T_micro, r, sigma) for s in S_values]

# 2. Optimal Stopping & Exercise Boundary Analysis
# An agent will exercise the real option only when S > S* (where Option Value > 0)
fiat_exercise_threshold = S_values[np.argmax(np.array(option_vals_fiat) > 1e-4)]
bc_exercise_threshold = S_values[np.argmax(np.array(option_vals_bc_low) > 1e-4)]

print("--- REAL-OPTIONS MICRO-CAPITAL ALLOCATION ---")
print(f"Fiat Minimum Exercise Payoff Threshold (S*): ${fiat_exercise_threshold:.4f}")
print(f"Blockchain Minimum Exercise Payoff Threshold (S*): ${bc_exercise_threshold:.4f}")
print(f"Efficiency Gain (Barrier Reduction): {fiat_exercise_threshold / max(bc_exercise_threshold, 1e-6):.1f}x")

# 3. Plotting the Real-Option Payoff Curves
plt.figure(figsize=(10, 6))
plt.plot(S_values * 100, np.array(option_vals_bc_low) * 100, label='Blockchain Micropayments (x402 on L2: K = $0.0015)', color='#2ca02c', linewidth=2.5)
plt.plot(S_values * 100, np.array(option_vals_bc_high) * 100, label='Blockchain Compute Tier (K = $0.01)', color='#1f77b4', linestyle='--', linewidth=2)
plt.plot(S_values * 100, np.array(option_vals_fiat) * 100, label='Traditional Fiat Rails (Visa/MC: K = $0.30)', color='#d62728', linestyle=':', linewidth=2.5)

plt.axvline(x=fiat_exercise_threshold * 100, color='#d62728', linestyle='--', alpha=0.5, label=f'Fiat Exercise Hurdle (~${fiat_exercise_threshold:.2f})')
plt.axvline(x=bc_exercise_threshold * 100, color='#2ca02c', linestyle='--', alpha=0.5, label=f'x402 Exercise Hurdle (~${bc_exercise_threshold:.4f})')

plt.title("Real-Options Framework: Agent Capital Allocation & The Micropayment Boundary", fontsize=12, fontweight='bold')
plt.xlabel("Expected Information Payoff / Value S (Cents USD)", fontsize=11)
plt.ylabel("Real Option Value V(S) (Cents USD)", fontsize=11)
plt.xlim(0, 50)
plt.ylim(0, 50)
plt.legend(loc='upper left', fontsize=10)
plt.grid(True, linestyle='--', alpha=0.6)
plt.tight_layout()

chart_path = os.path.join(output_dir, "real_options_micropayment_frontier.png")
plt.savefig(chart_path, dpi=300)
plt.close()

# 4. Save Numerical Results for Academic Reporting
summary_table = pd.DataFrame({
    'Expected_Payoff_USD': [0.001, 0.005, 0.010, 0.050, 0.100, 0.250, 0.500],
    'Option_Val_x402_L2': [black_scholes_call(s, K_blockchain_low, T_micro, r, sigma) for s in [0.001, 0.005, 0.010, 0.050, 0.100, 0.250, 0.500]],
    'Option_Val_Fiat': [black_scholes_call(s, K_fiat, T_micro, r, sigma) for s in [0.001, 0.005, 0.010, 0.050, 0.100, 0.250, 0.500]]
})
summary_table['Viable_on_Fiat'] = summary_table['Option_Val_Fiat'] > 0.001
summary_table['Viable_on_x402'] = summary_table['Option_Val_x402_L2'] > 0.0001

table_path = os.path.join(output_dir, "real_options_valuation_table.csv")
summary_table.to_csv(table_path, index=False)

print("\nReal-Options Valuation Table:")
print(summary_table.to_string(index=False))
print(f"\nSaved frontier plot to {chart_path} and valuation table to {table_path}")
